function signedTypeform({ signature, digest }) {
  if (
    typeof signature !== "string" ||
    typeof digest !== "string" ||
    !/^sha256=[A-Za-z0-9+/]{43}=$/.test(signature) ||
    !/^[A-Za-z0-9+/]{43}=$/.test(digest)
  )
    return false;
  let difference = 0;
  for (let index = 0; index < digest.length; index++)
    difference |= signature.charCodeAt(index + 7) ^ digest.charCodeAt(index);
  return difference === 0;
}
