return [{ json: authorized ? { authorized, body } : { authorized } }];

function mapLead({ response, formId, fields, schedulingUrl, presentationUrl }) {
  if (
    !response ||
    response.form_id !== formId ||
    !/^[a-zA-Z0-9_-]{1,128}$/.test(formId) ||
    typeof response.token !== "string" ||
