    !Array.isArray(response.answers)
  )
    throw new Error("Expected a completed response from the configured Typeform");
  const identifiers = [
    fields.first,
    fields.last,
    fields.department,
    fields.company,
    fields.email,
    fields.interest,
  ];
  if (
    new Set(identifiers).size !== 6 ||
    identifiers.some((id) => typeof id !== "string" || !id || id.startsWith("YOUR_"))
  ) {
    throw new Error("Configure six distinct Typeform field IDs");
  }
  const answer = (id, types) => {
    const matching = response.answers.filter((item) => item?.field?.id === id);
    if (matching.length !== 1 || !types.includes(matching[0].type))
      throw new Error("A required Typeform answer is missing or has the wrong type");
    return matching[0].type === "choice"
      ? matching[0].choice?.label
      : matching[0][matching[0].type];
  };
  const text = (val) => {
    if (typeof val !== "string" || !val.trim() || val.length > 500)
      throw new Error("Expected a nonempty Typeform text answer");
    return val.trim();
  };
  const firstname = text(answer(fields.first, ["text"]));
  const lastname = text(answer(fields.last, ["text"]));
  const industry = text(answer(fields.department, ["text", "choice"]));
  const company = text(answer(fields.company, ["text"]));
  const email = text(answer(fields.email, ["email"]));
  if (email.length > 254 || !/^[^\s@,;<>]+@[^\s@,;<>]+\.[^\s@,;<>]+$/.test(email))
    throw new Error("Expected one valid contact email");
  const interested = answer(fields.interest, ["boolean"]);
  if (typeof interested !== "boolean")
    throw new Error("Expected a boolean Typeform interest answer");
  if (
    interested &&
    [schedulingUrl, presentationUrl].some(
      (url) =>
        typeof url !== "string" ||
        !/^https:\/\/[a-z0-9.-]+\/[^\s]+$/i.test(url) ||
        /\.invalid\//i.test(url),
    )
  ) {
    throw new Error("Configure the scheduling and presentation links");
  }
  return {
    key: "typeform:" + formId + ":" + response.token,
    email,
    interested,
    properties: { email, firstname, lastname, industry, company },
    filter: [{ filters: [{ propertyName: "email", operator: "EQ", value: email }] }],
    subject: "So you're interested in growing your business",
    body:
      "Hello " +
      firstname +
      ",\n\nI'm glad to hear you're interested in our services. You can schedule a call with me here: " +
      schedulingUrl +
      ".\nUntil then, check out this presentation about how we can help your business: " +
      presentationUrl +
      ".\nLooking forward to talking to you!\n\nBest,\nTeam",
  };
}
